CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, summary TEXT NOT NULL, description TEXT, role TEXT, technologies TEXT, status TEXT, featured INTEGER DEFAULT 0, start_date TEXT, end_date TEXT, url TEXT, repository_url TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS experience (id TEXT PRIMARY KEY, organisation TEXT NOT NULL, title TEXT NOT NULL, summary TEXT, description TEXT, start_date TEXT NOT NULL, end_date TEXT, location TEXT, achievements TEXT, display_order INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS articles (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, summary TEXT, content TEXT, published_at TEXT, status TEXT NOT NULL, tags TEXT, external_url TEXT);
CREATE TABLE IF NOT EXISTS skills (id TEXT PRIMARY KEY, name TEXT NOT NULL, category TEXT, description TEXT, proficiency TEXT, display_order INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS timeline (id TEXT PRIMARY KEY, event_date TEXT NOT NULL, title TEXT NOT NULL, description TEXT, event_type TEXT, related_entity_type TEXT, related_entity_id TEXT);
CREATE TABLE IF NOT EXISTS capability_history (id TEXT PRIMARY KEY, capability_id TEXT NOT NULL, caller TEXT NOT NULL, input TEXT, output TEXT, success INTEGER NOT NULL, duration_ms INTEGER NOT NULL, executed_at TEXT NOT NULL, confirmation_status TEXT);
